INSERT INTO sensor_history
(
    plc_code,
    sensor_code,
    value,
    timestamp
)
SELECT
    plc_code,
    sensor_code,
    SUBSTRING_INDEX(GROUP_CONCAT(value ORDER BY timestamp DESC), ',', 1) AS value,
    FROM_UNIXTIME(
        CEILING(
            UNIX_TIMESTAMP(timestamp) / ${intervalSec}
        ) * ${intervalSec}
    ) AS time_bucket
FROM sensor_realtime
WHERE sensor_code = '${msg.sensor_code}'
AND plc_code = '${msg.plc_code}'
AND timestamp >= DATE_SUB(NOW(), INTERVAL 7 DAY)

AND timestamp <= FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(NOW()) / ${intervalSec}) * ${intervalSec})

GROUP BY
    plc_code,
    sensor_code,
    time_bucket
ON DUPLICATE KEY UPDATE
    value = VALUES(value);
`;

return msg;

