    }

    const pad = n => String(n).padStart(2, "0");

    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function formatDateTime(value) {
    if (!value) return null;

    const d = value instanceof Date ? value : new Date(value);

    if (isNaN(d.getTime())) {
        return null;
    }

    const pad = n => String(n).padStart(2, "0");

    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
           `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function sqlEscape(value) {
    if (value === null || value === undefined) {
        return "NULL";
    }

    if (typeof value === "number") {
        return value;
    }

    return "'" +
        String(value)
            .replace(/\\/g, "\\\\")
            .replace(/'/g, "''") +
        "'";
}

for (const row of rows) {

    const productionDate = formatDate(row.production_date);
    const startTime = formatDateTime(row.start_time);
    const endTime = formatDateTime(row.end_time);

    const data = {
        production_date: productionDate,
        group_id: row.group_id,
        data_cycle: row.data_cycle,
        total_data: row.total_data,
        high_count: row.high_count,
        low_count: row.low_count,
        avg_low: row.avg_low,
        min_low: row.min_low,
        max_low: row.max_low,
        avg_high: row.avg_high,
        min_high: row.min_high,
        max_high: row.max_high
    };

    const cycle = `${row.group_id}-${row.data_cycle}`;

values.push([
    projectCode,
    row.sensor_code,
    productionDate,
    cycle,
    startTime,
    endTime,
    row.status,
    JSON.stringify(data)
]);
}

const sqlValues = values
    .map(row => `(
        ${row.map(sqlEscape).join(",")}
    )`)
    .join(",");

msg.topic = `
INSERT INTO sensor_cycle
(
    project_code,
    sensor_code,
    production_date,
    cycle,
    start,
    end,
    status,
    data
)
VALUES
${sqlValues}

ON DUPLICATE KEY UPDATE
    start = VALUES(start),
    end = VALUES(end),
    status = VALUES(status),
    data = VALUES(data);
`;

return msg;

if (msg.error) {
    node.error("GAGAL membuat tabel", msg.error);
    return msg;
}

node.warn("BERHASIL menjalankan query database");

msg.payload = {
    status: "success",
    query: msg.topic,
    result: msg.payload
};

